<script setup>import {ref,defineAsyncComponent} from 'vue';import {useIntersectionObserver} from '@vueuse/core';defineProps({chart:String});const root=ref(null),seen=ref(false);const ChartBlock=defineAsyncComponent(()=>import('./ChartBlock.vue'));useIntersectionObserver(root,([{isIntersecting}])=>{if(isIntersecting)seen.value=true},{rootMargin:'350px'});</script><template><div ref="root" class="chart-lazy"><ChartBlock v-if="seen" :chart="chart"/><p v-else class="chart-loading">График загружается при приближении к экрану.</p></div></template>
